import React, { useState, useEffect } from "react";
import { db } from "../../firebaseConfig";
import { collection, query, where, getDocs } from "firebase/firestore";
import { useNavigate, useParams } from "react-router-dom"; // useParams to get the URL parameter
import "./ExamPage.css";

const ExamPage = () => {
  const { subject } = useParams(); // Extract the subject from the URL
  const [exam, setExam] = useState(null); // State to store the exam data
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchExam = async () => {
      if (!subject) return; // Ensure subject exists
      setLoading(true);
      try {
        const q = query(
          collection(db, "exams"),
          where("subject", "==", subject)
        );
        const querySnapshot = await getDocs(q);

        if (!querySnapshot.empty) {
          const examData = querySnapshot.docs[0].data(); // Assuming there's only one exam per subject
          setExam(examData); // Set exam data to state
        } else {
          alert("No exam found for this subject.");
        }
      } catch (error) {
        console.error("Error fetching exam:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchExam(); // Call fetchExam when the component mounts or subject changes
  }, [subject]);

  const startExam = () => {
    if (exam) {
      // Logic for starting the exam, for example navigating to a question page
      alert("Exam started!");
    }
  };

  if (loading) return <p>Loading exam...</p>;

  return (
    <div className="exam-page">
      <h2>Exam for {subject}</h2>
      {exam ? (
        <>
          <h3>Instructions:</h3>
          <p>{exam.instructions}</p>

          <h3>Questions:</h3>
          {exam.questions.map((q, index) => (
            <div key={index} className="question">
              <h4>Question {index + 1}</h4>
              <p>{q.question}</p>
              {/* Optionally, display input for answer or any other exam-related features */}
            </div>
          ))}

          <button onClick={startExam} className="start-exam-btn">
            Start Exam
          </button>
        </>
      ) : (
        <p>No exam found for this subject.</p>
      )}
    </div>
  );
};

export default ExamPage;
